 else {out.push(' '.repeat(d)+n.type+'['+n.id+'] '+n.name+' '+Math.round(n.width||0)+'x'+Math.round(n.height||0)+fill(n)+(n.cornerRadius?' r'+String(n.cornerRadius):''));}
