 out.push(' '.repeat(d)+n.type+'['+n.id+'] '+n.name+' '+Math.round(n.width||0)+'x'+Math.round(n.height||0)+fill(n)+extra);}
 if('children' in n && n.type!=='INSTANCE' && d<maxd) n.children.forEach(c=>walk(c,d+1,maxd));
}
